import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import {
	radioButtonDefault,
	radioButtonIndeterminate,
	radioButtonSelected,
} from "../../../icons";
import FormControl from "../../functional-components/form-control/form-control";
import { attachElementInternals } from "../../utils/element-internals";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { hasSlot } from "../../utils/slot";

let id = 0;

/**
 * @since 0.0.11
 * @status experimental
 *
 * @description Radios allow the user to select one option from a group of many. Radios are designed to be used with hbr-radio-group. As such, all of the examples on this page utilize them to demonstrate their correct usage.
 *
 * @slot - The radio's label.
 * @slot label - The radio's top label.
 * @slot label-suffix - Non-interactive content to display inline with the radio label.
 * @slot label-info - Interactive informational content, such as a tooltip trigger, displayed next to the radio label.
 * @slot help-text - The radio's help text.
 * @slot description - The radio's description text (v2.14.11)
 *
 * @part form-control - The root wrapper element
 * @part base - The component's base wrapper.
 * @part control - The radio control.
 * @part default-icon - The container the wraps the default icon.
 * @part checked-icon - The container the wraps the checked icon.
 * @part indeterminate-icon - The container the wraps the indeterminate icon.
 * @part content - The radio content wrapper.
 * @part label - The radio label.
 * @part input - The input element.
 * @part help-text - The help text wrapper element
 * @part description - The description text element (v2.14.11)
 */

@Component({
	tag: "hbr-radio",
	styleUrl: "radio.scss",
	shadow: true,
	formAssociated: true,
})
export class Radio {
	inputId = `radio-${++id}`;
	labelId = `radio-label-${id}`;
	_helpTextId = `radio-helpTextId-${id}`;
	input: HTMLInputElement;
	private _ariaLabel: string;

	@Element() host: HTMLHbrRadioElement;

	private internals?: ElementInternals;

	@State() hasFocus = false;
	@State() hasContent = false;
	@State() hasHelpTextSlot = false;
	@State() hasLabelSlot = false;
	@State() hasLabelInfoSlot = false;
	@State() hasFrontSlot = false;
	@State() hasRearSlot = false;
	@State() hasElementSuffix = false;
	@State() hasDescriptionSlot = false;

	/** The radio's name attribute. */
	@Prop({ reflect: true }) name: string;

	/** The radio's value attribute. */
	@Prop({ reflect: true }) value: string;

	/** The radio's label attribute. */
	@Prop({ reflect: true }) label = "";

	/** The radio's help text. */
	@Prop({ reflect: true }) helpText = "";

	/** The radio's help text id. */
	@Prop({ reflect: true }) helpTextId = "";

	/** Set to true to disable the radio. */
	@Prop({ reflect: true }) disabled = false;

	/** Set to true to make the radio a required field. */
	@Prop({ reflect: true }) required = false;

	/** Set to true to make the radio to error state. */
	@Prop({ reflect: true }) error = false;

	/* radio size */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	@Prop({ mutable: true, reflect: true }) indeterminate = false;

	/** Set to true to draw the radio in a checked state. */
	@Prop({ mutable: true, reflect: true }) checked = false;

	@Prop({ mutable: true, reflect: true }) sentiment = "interact";

	/**
	 * This will be true when the control is in an invalid state. Validity in range inputs is determined by the message
	 * provided by the `setCustomValidity` method.
	 */
	@Prop({ mutable: true, reflect: true }) invalid = false;

	/* tabindex */
	@Prop({ mutable: true }) tabidx: string | boolean = false;

	/** Tooltip content if the icon button serves as a tooltip reference. */
	@Prop({ reflect: true }) tooltip: string;

	/** Indicates that the radio button should receive focus on page load. */
	@Prop() autofocus: boolean;

	/** Attributes related to screen readers. */
	@Prop() aria: {
		label?: string;
	};

	@Watch("checked")
	@Watch("indeterminate")
	handleCheckedChange() {
		if (this.checked) {
			this.getSiblingRadios().forEach((radio) => {
				radio.checked = false;
			});
		}
		if (this.input) {
			this.input.checked = this.checked;
			this.internals?.setFormValue(this.checked ? this.value || "on" : null);
		}
		this.hbrChange.emit();
		this.handleFirstRadioTabindex();
	}

	private handleFirstRadioTabindex = () => {
		const group = this.host.closest(
			"hbr-radio-group",
		) as HTMLHbrRadioGroupElement;
		group?.getRadioTabindexStatus();
	};

	@Watch("helpText")
	@Watch("label")
	handleLabelChange() {
		this.handleSlotChange();
	}

	@Watch("disabled")
	handleDisabledChange() {
		// Disabled form controls are always valid, so we need to recheck validity when the state changes
		if (this.input) {
			this.input.disabled = this.disabled;
		}
		this.handleFirstRadioTabindex();
	}

	/** Emitted when the control loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur: EventEmitter;

	/** Emitted when the control's checked state changes. */
	@Event({ eventName: "hbr-change" }) hbrChange: EventEmitter;

	/** Emitted when click. */
	@Event({ eventName: "hbr-click" }) hbrClick: EventEmitter;

	/** Emitted when the control gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus: EventEmitter;

	connectedCallback() {
		this.internals ??= attachElementInternals(this.host);
		this.handleClick = this.handleClick.bind(this);
		this.handleBlur = this.handleBlur.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleKeyDown = this.handleKeyDown.bind(this);
		this.handleMouseDown = this.handleMouseDown.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleDisabledChange = this.handleDisabledChange.bind(this);
		this.host.shadowRoot.addEventListener("slotchange", this.handleSlotChange);
	}

	componentWillLoad() {
		this.handleSlotChange();
	}

	disconnectedCallback() {
		this.host.shadowRoot.removeEventListener(
			"slotchange",
			this.handleSlotChange,
		);
	}

	componentDidLoad() {
		if (this.input) {
			this.input.indeterminate = this.indeterminate;
		}
		this.handleFirstRadioTabindex();
		setTimeout(() => {
			if (this.autofocus && document.activeElement !== this.host) {
				this.input.focus();
			}
		});
	}

	/** Simulates a click on the radio. */
	@Method()
	async setClick() {
		this.input?.click();
	}

	/** Sets focus on the radio. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.input?.focus(options);
	}

	/** Removes focus from the radio. */
	@Method()
	async removeFocus() {
		this.input?.blur();
	}

	/** Checks for validity and shows the browser's validation message if the control is invalid. */
	@Method()
	async reportValidity() {
		return this.input?.reportValidity();
	}

	/** Sets a custom validation message. If `message` is not empty, the field will be considered invalid. */
	@Method()
	async setCustomValidity(message: string) {
		this.input?.setCustomValidity(message);
	}

	getAllRadios() {
		const parent = this.host.closest("hbr-radio-group");

		if (!parent) return [];

		return Array.from(parent.querySelectorAll("hbr-radio"));
	}

	getSiblingRadios() {
		return this.getAllRadios().filter(
			(radio) => radio !== this.host,
		) as HTMLHbrRadioElement[];
	}

	handleClick() {
		this.checked = this.input?.checked;
		this.indeterminate = false;
		this.hbrClick.emit();
	}

	handleBlur() {
		this.hasFocus = false;
		this.hbrBlur.emit();
	}

	handleFocus() {
		this.hasFocus = true;
		this.hbrFocus.emit();
	}

	handleKeyDown(event: KeyboardEvent) {
		if (
			["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(event.key)
		) {
			const radios = this.getAllRadios().filter((radio) => !radio.disabled);
			const incr = ["ArrowUp", "ArrowLeft"].includes(event.key) ? -1 : 1;
			let index = radios.indexOf(this.host) + incr;
			if (index < 0) index = radios.length - 1;
			if (index > radios.length - 1) index = 0;

			radios.forEach((radio) => {
				radio.checked = false;
			});
			if (radios[index]) {
				radios[index].shadowRoot.querySelector("input")?.click();
				radios[index].setFocus();
			}

			event.preventDefault();
		}
	}

	handleMouseDown(event: MouseEvent) {
		// Prevent clicks on the label from briefly blurring the input
		event.preventDefault();
		this.input.focus();
	}

	renderIcon = () => {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		if (this.error && !this.checked && !this.indeterminate && !this.disabled) {
			return (
				<span part="error-icon-wrapper" class="radio__icon radio__icon_error">
					<hbr-icon
						part="error-icon"
						asset={
							customSystemIcons?.["radio-button-default"] || radioButtonDefault
						}
					/>
				</span>
			);
		}
		if (!this.checked && !this.indeterminate) {
			// Default
			return (
				<span part="default-icon-wrapper" class="radio__icon">
					<hbr-icon
						part="default-icon"
						asset={
							customSystemIcons?.["radio-button-default"] || radioButtonDefault
						}
					/>
				</span>
			);
		}
		if (this.checked) {
			// Check
			return (
				<span part="checked-icon-wrapper" class="radio__icon">
					<hbr-icon
						part="checked-icon"
						asset={
							customSystemIcons?.["radio-button-selected"] ||
							radioButtonSelected
						}
					/>
				</span>
			);
		}
		if (!this.checked && this.indeterminate) {
			// Indeterminate
			return (
				<span part="indeterminate-icon-wrapper" class="radio__icon">
					<hbr-icon
						part="indeterminate-icon"
						asset={
							customSystemIcons?.["radio-button-indeterminate"] ||
							radioButtonIndeterminate
						}
					/>
				</span>
			);
		}
	};

	handleSlotChange() {
		this.hasHelpTextSlot = hasSlot(this.host, "help-text");
		this.hasLabelSlot = hasSlot(this.host, "label");
		this.hasLabelInfoSlot = hasSlot(this.host, "label-info");
		this.hasFrontSlot = hasSlot(this.host, "front");
		this.hasRearSlot = hasSlot(this.host, "rear");
		this.hasContent = hasSlot(this.host);
		this._ariaLabel = this.aria?.label || this.host.textContent;
		this.hasElementSuffix = hasSlot(this.host, "element-suffix");
		this.hasDescriptionSlot = hasSlot(this.host, "description");
	}

	renderContent = () => {
		return (
			<span
				part={`content ${this.checked ? "content-checked" : ""}`}
				id={this.labelId}
				class={{ radio__label: this.hasContent }}
			>
				<slot onSlotchange={this.handleSlotChange} />
			</span>
		);
	};

	renderRadio() {
		const describedHelpId =
			this.helpTextId || this.hasHelpTextSlot ? this._helpTextId : "";
		const tooltipId = this.tooltip ? `${this.inputId}-tooltip` : "";
		const describedId =
			describedHelpId || tooltipId
				? `${describedHelpId} ${tooltipId}`
				: undefined;
		return (
			<label
				part="base"
				class={{
					radio: true,
					"radio--checked": this.checked,
					"radio--disabled": this.disabled,
					"radio--focused": this.hasFocus,
					"radio--indeterminate": this.indeterminate,
					"radio--size-small": this.size === "small",
					"radio--size-medium": this.size === "medium",
					"radio--size-large": this.size === "large",
					"radio--has-description": this.hasDescriptionSlot,
				}}
				htmlFor={this.inputId}
				onKeyDown={this.handleKeyDown}
				onMouseDown={this.handleMouseDown}
			>
				<span
					part={`control ${this.hasFocus ? "control-focus" : ""}`}
					class="radio__control"
				>
					{this.renderIcon()}

					<input
						part="input"
						ref={(el) => {
							this.input = el;
						}}
						id={this.inputId}
						type="radio"
						name={this.name}
						value={this.value}
						checked={this.checked}
						disabled={this.disabled}
						required={this.required}
						tabindex={
							this.tabidx ? `${this.tabidx}` : this.checked ? "0" : "-1"
						}
						role="radio"
						aria-checked={this.checked ? "true" : "false"}
						aria-disabled={this.disabled ? "true" : "false"}
						aria-describedby={describedId}
						aria-invalid={this.invalid ? "true" : false}
						onClick={this.handleClick}
						onBlur={this.handleBlur}
						onFocus={this.handleFocus}
						autofocus={this.autofocus}
						aria-label={this._ariaLabel}
					/>
				</span>
				{this.hasDescriptionSlot ? (
					<span class={"main-container"}>
						{this.renderContent()}
						<span part={"description"} class="radio__description">
							<slot name="description" onSlotchange={this.handleSlotChange} />
						</span>
					</span>
				) : (
					this.renderContent()
				)}
			</label>
		);
	}

	render() {
		return (
			<Host>
				<FormControl
					inputId=""
					labelId={this.labelId}
					size={this.size}
					isRequired={this.required}
					hasLabelSlot={this.hasLabelSlot}
					hasLabelInfoSlot={this.hasLabelInfoSlot}
					hasFrontSlot={this.hasFrontSlot}
					hasRearSlot={this.hasRearSlot}
					hasElementSuffix={this.hasElementSuffix}
					hasHelpTextSlot={this.hasHelpTextSlot}
					label={this.label}
					helpText={this.helpText}
					helpTextId={this.helpTextId || this._helpTextId}
					hasError={this.error}
					isDisabled={this.disabled}
					tooltip={this.tooltip}
					tooltipId={this.tooltip ? `${this.inputId}-tooltip` : undefined}
				>
					{this.renderRadio()}
				</FormControl>
			</Host>
		);
	}
}
